(function(){const panels=document.querySelectorAll("#performance-drivers details.metric-detail");document.addEventListener("toggle",function(e){const active=e.target;if(!active.matches || !active.matches("#performance-drivers details.metric-detail") || !active.open)return;panels.forEach(p=>{if(p!==active)p.open=false})},true);document.addEventListener("click",function(e){if(e.target.closest("#performance-drivers details.metric-detail"))return;panels.forEach(p=>p.open=false)});})();
